import assert from "node:assert/strict";
import test from "node:test";

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

import type { BatchRunner } from "../../src/batch.js";
import type {
  BatchProgress,
  ChildResult,
  SpawnBatchResult,
  SpawnTask,
} from "../../src/domain.js";
import { taskIdFor } from "../../src/domain.js";
import { registerSpawnPiTool, SpawnPiSchema } from "../../src/tools.js";

interface TestTheme {
  bold: (text: string) => string;
  fg: (_color: string, text: string) => string;
}

const theme: TestTheme = {
  bold: (text: string) => text,
  fg: (_color: string, text: string) => text,
};

type RenderDetails =
  | { phase: "working"; progress: BatchProgress }
  | { phase: "finished"; result: SpawnBatchResult }
  | SpawnBatchResult
  | undefined;

interface Rendered {
  render: (width: number) => string[];
}

interface CapturedTool {
  execute: (
    callId: string,
    params: { tasks: SpawnTask[] },
    signal: AbortSignal,
    onUpdate: undefined,
    context: { cwd: string; modelRegistry: { getAvailable: () => unknown[] } }
  ) => Promise<{ content: { text: string }[] }>;
  parameters: {
    properties: {
      tasks: { items: { properties: { role: { description: string } } } };
    };
  };
  promptGuidelines: string[];
  renderCall: (args: { tasks?: SpawnTask[] }, theme: TestTheme) => Rendered;
  renderResult: (
    result: {
      content: { type: string; text?: string }[];
      details: RenderDetails;
    },
    options: { expanded: boolean; isPartial: boolean },
    theme: TestTheme,
    context: { args: { tasks: SpawnTask[] } }
  ) => Rendered;
}

const unusedRunner: BatchRunner = {
  run() {
    throw new Error("The renderer tests do not run the batch runner");
  },
};

const registeredTool = (runner: BatchRunner = unusedRunner): CapturedTool => {
  let tool: CapturedTool | undefined;
  registerSpawnPiTool(
    // SAFETY: This test double is used only to capture the tool definition, the sole ExtensionAPI member registerSpawnPiTool accesses.
    // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- ExtensionAPI is intentionally narrowed by this test double.
    {
      registerTool(definition: CapturedTool) {
        tool = definition;
      },
    } as unknown as ExtensionAPI,
    runner,
    () => "parent",
    {
      config: { defaults: {}, orchestrator: { enabled: false }, roles: {} },
      ok: true,
      path: "/config.json",
    }
  );
  if (!tool) {
    throw new Error("The test double did not capture the tool definition");
  }
  return tool;
};

test("omits placement from the public task schema", () => {
  assert.equal(
    "placement" in SpawnPiSchema.properties.tasks.items.properties,
    false
  );
});

const child = (overrides: Partial<ChildResult> = {}): ChildResult => ({
  paneClosed: true,
  requestIndex: 0,
  status: "succeeded",
  taskId: taskIdFor(0),
  truncated: false,
  ...overrides,
});

const render = (
  tool: CapturedTool,
  details: RenderDetails,
  args: { tasks: SpawnTask[] },
  expanded = false,
  isPartial = false
): string =>
  tool
    .renderResult(
      { content: [{ text: "raw text", type: "text" }], details },
      { expanded, isPartial },
      theme,
      { args }
    )
    .render(500)
    .join("\n")
    .replaceAll(/ +\n/gu, "\n")
    .trimEnd();

test("guidance prevents requests for unconfigured roles", () => {
  const tool = registeredTool();
  assert.match(
    tool.parameters.properties.tasks.items.properties.role.description,
    /Exact configured Child Role name/u
  );
  assert.ok(
    tool.promptGuidelines.some((guideline: string) =>
      /otherwise omit role/u.test(guideline)
    )
  );
});

test("renders a stable partial card with every requested task in request order", () => {
  const tool = registeredTool();
  const output = render(
    tool,
    {
      phase: "working",
      progress: {
        completed: 1,
        results: [
          child({
            location: { paneId: "pane-2", tabId: "tab-5", workspaceId: "w" },
            paneClosed: false,
            requestIndex: 1,
            status: "blocked",
            taskId: taskIdFor(1),
          }),
        ],
        total: 3,
      },
    },
    {
      tasks: [
        { prompt: "one", role: "explore\n\u001B[31m" },
        { prompt: "two", role: "reviewer" },
        { prompt: "three" },
      ],
    },
    false,
    true
  );

  assert.match(output, /^working · 1 of 3 settled/u);
  assert.match(output, /◌ task-1 \[explore \[31m\] working/u);
  assert.match(output, /! task-2 \[reviewer\] needs input · tab-5\/pane-2/u);
  assert.match(output, /◌ task-3 working/u);
});

test("renders collapsed and expanded final rows with the approved visibility policy", () => {
  const tool = registeredTool();
  const result = {
    requested: 3,
    results: [
      child({
        selection: {
          model: { id: "model", provider: "openai" },
          modelSource: "role",
          thinkingLevel: "low",
          thinkingSource: "default",
        },
        sessionId: "session-1",
        summary: "finished",
        truncated: true,
      }),
      child({
        error: { code: "blocked", message: "Please choose" },
        location: { paneId: "pane-3", tabId: "tab-2", workspaceId: "w" },
        paneClosed: false,
        requestIndex: 1,
        status: "blocked",
        taskId: taskIdFor(1),
      }),
      child({
        error: {
          code: "model_routing_failed",
          message: "No configured model is available",
        },
        requestIndex: 2,
        status: "failed",
        taskId: taskIdFor(2),
      }),
    ],
  };
  const args = {
    tasks: [
      { prompt: "one", role: "explore" },
      { prompt: "two", role: "reviewer" },
      { prompt: "three" },
    ],
  };
  const collapsed = render(tool, { phase: "finished", result }, args);
  const expanded = render(tool, { phase: "finished", result }, args, true);

  assert.match(collapsed, /^× incomplete · 1 of 3 complete/u);
  assert.match(collapsed, /✓ task-1 \[explore\]/u);
  assert.doesNotMatch(
    collapsed,
    /task-1 \[explore\] complete|session-1|openai\/model|finished|Please choose/u
  );
  assert.match(collapsed, /! task-2 \[reviewer\] needs input · tab-2\/pane-3/u);
  assert.match(collapsed, /× task-3 incomplete · model unavailable/u);
  assert.match(
    expanded,
    /finished\nsummary truncated\nmodel: openai\/model\nthinking: low\nmodel selection: role\nthinking selection: default\nsession: session-1/u
  );
  assert.match(expanded, /Please choose/u);
});

test("renders successful batches with aggregate completion and icon-only child rows", () => {
  const tool = registeredTool();
  const result = {
    requested: 2,
    results: [child(), child({ requestIndex: 1, taskId: taskIdFor(1) })],
  };
  const output = render(
    tool,
    { phase: "finished", result },
    {
      tasks: [
        { prompt: "one", role: "explore" },
        { prompt: "two", role: "reviewer" },
      ],
    }
  );

  assert.match(output, /^✓ 2 of 2 tasks complete/u);
  assert.match(output, /✓ task-1 \[explore\]/u);
  assert.match(output, /✓ task-2 \[reviewer\]/u);
  assert.equal(output.match(/complete/gu)?.length, 1);
});

test("returns simplified plain-text summaries for successful and mixed executions", async () => {
  const results = [
    {
      requested: 1,
      results: [child({ role: "explore", sessionId: "session-1" })],
    },
    {
      requested: 2,
      results: [
        child({ role: "explore" }),
        child({
          error: { code: "blocked", message: "Please choose" },
          paneClosed: false,
          requestIndex: 1,
          role: "reviewer",
          sessionId: "session-2",
          status: "blocked",
          taskId: taskIdFor(1),
        }),
      ],
    },
  ];
  const tool = registeredTool({
     async run() {
      const result = results.shift();
      if (!result) {
        throw new Error("The test runner ran out of results");
      }
      return Promise.resolve(result);
    },
  });
  const context = {
    cwd: "/repo",
    modelRegistry: { getAvailable: () => [] },
  };

  const successful = await tool.execute(
    "call-1",
    { tasks: [{ prompt: "one", role: "explore" }] },
    new AbortController().signal,
    undefined,
    context
  );
  const mixed = await tool.execute(
    "call-2",
    {
      tasks: [
        { prompt: "one", role: "explore" },
        { prompt: "two", role: "reviewer" },
      ],
    },
    new AbortController().signal,
    undefined,
    context
  );

  assert.equal(
    successful.content[0].text,
    "spawn_pi: ✓ 1 of 1 task complete\n✓ task-1 [explore] · session session-1"
  );
  assert.equal(
    mixed.content[0].text,
    "spawn_pi: ! needs input · 1 of 2 complete\n✓ task-1 [explore]\n! task-2 [reviewer]: needs input · session session-2 · Please choose"
  );
});

test("supports legacy final details and safely falls back to raw content", () => {
  const tool = registeredTool();
  const legacy = {
    requested: 1,
    results: [
      child({
        error: { code: "start_failed", message: "broken" },
        status: "failed",
      }),
    ],
  };

  assert.match(
    render(tool, legacy, { tasks: [{ prompt: "one" }] }),
    /^× incomplete · 0 of 1 complete/u
  );
  assert.equal(
    render(tool, undefined, { tasks: [{ prompt: "one" }] }),
    "raw text"
  );
  assert.equal(
    render(tool, legacy, { tasks: [{ prompt: "one" }] }, false, true),
    "raw text"
  );
  assert.equal(
    tool.renderCall({}, theme).render(500).join("\n").trimEnd(),
    "spawn_pi"
  );
  assert.equal(
    tool
      .renderCall({ tasks: [{ prompt: "one" }] }, theme)
      .render(500)
      .join("\n")
      .trimEnd(),
    "spawn_pi 1 task"
  );
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import test from "node:test";

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

import type { ChildRolesConfigLoadResult } from "../../src/model-routing.js";
import {
  findOrchestratorState,
  ORCHESTRATOR_INSTRUCTIONS,
  ORCHESTRATOR_STATE_ENTRY,
  readOrchestratorState,
  registerOrchestrator,
} from "../../src/orchestrator.js";

interface SessionEntry {
  type: string;
  customType?: string;
  data?: unknown;
}
interface OrchestratorStateData {
  enabled: boolean;
}
interface HarnessEvent {
  reason?: "new" | "resume" | "fork";
  previousSessionFile?: string;
  systemPrompt?: string;
}
interface HarnessContext {
  hasUI: boolean;
  sessionManager: { getEntries: () => SessionEntry[] };
  ui: {
    theme: { fg: (name: string, value: string) => string };
    setStatus: (key: string, value: string | undefined) => void;
    notify: (message: string, level?: string) => void;
  };
}
type Handler = (
  event: HarnessEvent,
  ctx: HarnessContext
) => { systemPrompt: string } | undefined;
interface Command {
  handler: (args: string, ctx: HarnessContext) => Promise<void>;
}

const harness = (
  configResult: ChildRolesConfigLoadResult,
  activeTools = ["spawn_pi"]
) => {
  const handlers = new Map<string, Handler[]>();
  const commands = new Map<string, Command>();
  const appended: { customType: string; data: OrchestratorStateData }[] = [];
  const notifications: { message: string; level?: string }[] = [];
  const statuses: (string | undefined)[] = [];
  let sessionEntries: SessionEntry[] = [];
  const ctx: HarnessContext = {
    hasUI: true,
    sessionManager: { getEntries: () => sessionEntries },
    ui: {
      notify: (message: string, level?: string) =>
        notifications.push({ level, message }),
      setStatus: (_key: string, value: string | undefined) =>
        statuses.push(value),
      theme: { fg: (_name: string, value: string) => value },
    },
  };
  // SAFETY: This test double provides every ExtensionAPI member registerOrchestrator invokes with behavior captured by this harness.
  const pi = {
    appendEntry(customType: string, data: OrchestratorStateData) {
      appended.push({ customType, data });
    },
    getActiveTools() {
      return activeTools;
    },
    on(name: string, handler: Handler) {
      handlers.set(name, [...(handlers.get(name) ?? []), handler]);
    },
    registerCommand(name: string, command: Command) {
      commands.set(name, command);
    },
  } as ExtensionAPI;
  registerOrchestrator(pi, configResult);
  const command = commands.get("orchestrator");
  if (!command) {
    throw new Error("orchestrator command was not registered");
  }
  return {
    appended,
    command,
    ctx,
    emit(name: string, event: HarnessEvent, context = ctx) {
      let result: ReturnType<Handler>;
      for (const handler of handlers.get(name) ?? []) {
        result = handler(event, context);
      }
      return result;
    },
    notifications,
    setEntries(entries: SessionEntry[]) {
      sessionEntries = entries;
    },
    statuses,
  };
};

const enabledConfig: ChildRolesConfigLoadResult = {
  config: { defaults: {}, orchestrator: { enabled: true }, roles: {} },
  ok: true,
  path: "/config.json",
};

const withParentEnvironment =  async (run: () => Promise<void>): Promise<void> => {
  const previous = {
    HERDR_ENV: process.env.HERDR_ENV,
    HERDR_PANE_ID: process.env.HERDR_PANE_ID,
    HERDR_SOCKET_PATH: process.env.HERDR_SOCKET_PATH,
    HERDR_TAB_ID: process.env.HERDR_TAB_ID,
    HERDR_WORKSPACE_ID: process.env.HERDR_WORKSPACE_ID,
  };
  Object.assign(process.env, {
    HERDR_ENV: "1",
    HERDR_PANE_ID: "pane",
    HERDR_SOCKET_PATH: "/tmp/herdr.sock",
    HERDR_TAB_ID: "tab",
    HERDR_WORKSPACE_ID: "workspace",
  });
  return Promise.resolve(run()).finally(() => {
    if (previous.HERDR_ENV === undefined) {
      delete process.env.HERDR_ENV;
    } else {
      process.env.HERDR_ENV = previous.HERDR_ENV;
    }
    if (previous.HERDR_PANE_ID === undefined) {
      delete process.env.HERDR_PANE_ID;
    } else {
      process.env.HERDR_PANE_ID = previous.HERDR_PANE_ID;
    }
    if (previous.HERDR_SOCKET_PATH === undefined) {
      delete process.env.HERDR_SOCKET_PATH;
    } else {
      process.env.HERDR_SOCKET_PATH = previous.HERDR_SOCKET_PATH;
    }
    if (previous.HERDR_TAB_ID === undefined) {
      delete process.env.HERDR_TAB_ID;
    } else {
      process.env.HERDR_TAB_ID = previous.HERDR_TAB_ID;
    }
    if (previous.HERDR_WORKSPACE_ID === undefined) {
      delete process.env.HERDR_WORKSPACE_ID;
    } else {
      process.env.HERDR_WORKSPACE_ID = previous.HERDR_WORKSPACE_ID;
    }
  });
};

test("finds the latest session-wide state and reads it from JSONL", () => {
  const entries = [
    {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: true },
      type: "custom",
    },
    { customType: "other", data: { enabled: true }, type: "custom" },
    {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: false },
      type: "custom",
    },
  ];
  assert.equal(findOrchestratorState(entries), false);

  const directory = mkdtempSync(path.join(tmpdir(), "orchestrator-"));
  const sessionPath = path.join(directory, "session.jsonl");
  try {
    writeFileSync(
      sessionPath,
      [
        JSON.stringify({ type: "session" }),
        "malformed",
        ...entries.map((entry) => JSON.stringify(entry)),
      ].join("\n")
    );
    assert.equal(readOrchestratorState(sessionPath), false);
  } finally {
    rmSync(directory, { force: true, recursive: true });
  }
});

test("uses the configured default, persists it, injects instructions, and toggles", async () => {
  await withParentEnvironment(async () => {
    const h = harness(enabledConfig);
    h.emit("session_start", { reason: "new" });
    assert.deepEqual(h.appended, [
      { customType: ORCHESTRATOR_STATE_ENTRY, data: { enabled: true } },
    ]);
    assert.equal(h.statuses.at(-1), "orchestrator");
    assert.deepEqual(h.emit("before_agent_start", { systemPrompt: "base" }), {
      systemPrompt: `base\n\n${ORCHESTRATOR_INSTRUCTIONS}`,
    });

    await h.command.handler("off", h.ctx);
    assert.deepEqual(h.appended.at(-1), {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: false },
    });
    assert.equal(
      h.emit("before_agent_start", { systemPrompt: "base" }),
      undefined
    );
    assert.deepEqual(h.notifications.at(-1), {
      level: "info",
      message: "○ Orchestrator disabled",
    });

    await h.command.handler("", h.ctx);
    assert.deepEqual(h.appended.at(-1), {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: true },
    });
    assert.deepEqual(h.notifications.at(-1), {
      level: "info",
      message: "✓ Orchestrator enabled",
    });
  });
});

test("status reports configured Child Roles and descriptions", async () => {
  await withParentEnvironment(async () => {
    const h = harness({
      ...enabledConfig,
      config: {
        ...enabledConfig.config,
        roles: {
          explore: {
            description: "Read-only; reconnaissance.",
            prompt: "Inspect only.",
          },
          reviewer: { prompt: "Review changes." },
        },
      },
    });
    h.emit("session_start", { reason: "new" });

    await h.command.handler("status", h.ctx);

    assert.deepEqual(h.notifications.at(-1), {
      level: "info",
      message:
        "● Orchestrator enabled\n  Roles  explore (Read-only; reconnaissance.) · reviewer",
    });
  });
});

test("status reports when no Child Roles are configured", async () => {
  await withParentEnvironment(async () => {
    const h = harness(enabledConfig);
    h.emit("session_start", { reason: "new" });
    await h.command.handler("off", h.ctx);

    await h.command.handler("status", h.ctx);

    assert.deepEqual(h.notifications.at(-1), {
      level: "info",
      message: "○ Orchestrator disabled\n  Roles  none",
    });
  });
});

test("restores state across branches and forks inherit the source session current state", async () => {
  await withParentEnvironment( async () => {
    const directory = mkdtempSync(path.join(tmpdir(), "orchestrator-fork-"));
    const source = path.join(directory, "source.jsonl");
    try {
      writeFileSync(
        source,
        [
          JSON.stringify({ type: "session" }),
          JSON.stringify({
            customType: ORCHESTRATOR_STATE_ENTRY,
            data: { enabled: false },
            type: "custom",
          }),
          JSON.stringify({
            customType: ORCHESTRATOR_STATE_ENTRY,
            data: { enabled: true },
            type: "custom",
          }),
        ].join("\n")
      );
      const h = harness({
        ...enabledConfig,
        config: { ...enabledConfig.config, orchestrator: { enabled: false } },
      });
      h.setEntries([
        {
          customType: ORCHESTRATOR_STATE_ENTRY,
          data: { enabled: false },
          type: "custom",
        },
      ]);
      h.emit("session_start", { previousSessionFile: source, reason: "fork" });
      assert.deepEqual(h.appended.at(-1), {
        customType: ORCHESTRATOR_STATE_ENTRY,
        data: { enabled: true },
      });
      assert.deepEqual(h.emit("before_agent_start", { systemPrompt: "base" }), {
        systemPrompt: `base\n\n${ORCHESTRATOR_INSTRUCTIONS}`,
      });
    } finally {
      rmSync(directory, { force: true, recursive: true });
    }
    return Promise.resolve();
  });
});

test("hands current state to in-memory forks", async () => {
  await withParentEnvironment(async () => {
    const source = harness({
      ...enabledConfig,
      config: { ...enabledConfig.config, orchestrator: { enabled: false } },
    });
    source.emit("session_start", { reason: "new" });
    await source.command.handler("on", source.ctx);
    source.emit("session_before_fork", {});

    const fork = harness({
      ...enabledConfig,
      config: { ...enabledConfig.config, orchestrator: { enabled: false } },
    });
    fork.emit("session_start", { reason: "fork" });
    assert.deepEqual(fork.appended.at(-1), {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: true },
    });
  });
});

test("keeps enabled preference while spawn_pi is temporarily inactive", async () => {
  await withParentEnvironment( async () => {
    const activeTools: string[] = [];
    const h = harness(enabledConfig, activeTools);
    h.setEntries([
      {
        customType: ORCHESTRATOR_STATE_ENTRY,
        data: { enabled: true },
        type: "custom",
      },
    ]);
    h.emit("session_start", { reason: "resume" });
    assert.equal(
      h.emit("before_agent_start", { systemPrompt: "base" }),
      undefined
    );
    activeTools.push("spawn_pi");
    assert.deepEqual(h.emit("before_agent_start", { systemPrompt: "base" }), {
      systemPrompt: `base\n\n${ORCHESTRATOR_INSTRUCTIONS}`,
    });
    return Promise.resolve();
  });
});

test("disables and persists while spawn_pi is inactive", async () => {
  await withParentEnvironment(async () => {
    const activeTools: string[] = [];
    const h = harness(enabledConfig, activeTools);
    h.setEntries([
      {
        customType: ORCHESTRATOR_STATE_ENTRY,
        data: { enabled: true },
        type: "custom",
      },
    ]);
    h.emit("session_start", { reason: "resume" });

    await h.command.handler("off", h.ctx);
    assert.deepEqual(h.appended.at(-1), {
      customType: ORCHESTRATOR_STATE_ENTRY,
      data: { enabled: false },
    });

    activeTools.push("spawn_pi");
    assert.equal(
      h.emit("before_agent_start", { systemPrompt: "base" }),
      undefined
    );
  });
});

test("reports invalid command usage", async () => {
  await withParentEnvironment(async () => {
    const h = harness(enabledConfig);
    h.emit("session_start", { reason: "new" });

    await h.command.handler("invalid", h.ctx);

    assert.deepEqual(h.notifications.at(-1), {
      level: "error",
      message: "! Usage: /orchestrator [on|off|status|toggle]",
    });
  });
});

test("keeps the mode unavailable in children, outside Herdr, and with invalid config", async () => {
  await withParentEnvironment(async () => {
    const child = harness(enabledConfig, []);
    child.emit("session_start", { reason: "new" });
    assert.equal(
      child.emit("before_agent_start", { systemPrompt: "base" }),
      undefined
    );
    await child.command.handler("status", child.ctx);
    assert.deepEqual(child.notifications.at(-1), {
      level: "warning",
      message:
        "△ Orchestrator unavailable\n  Requires a Herdr Parent with spawn_pi active.",
    });

    delete process.env.HERDR_ENV;
    delete process.env.HERDR_PANE_ID;
    delete process.env.HERDR_SOCKET_PATH;
    delete process.env.HERDR_TAB_ID;
    delete process.env.HERDR_WORKSPACE_ID;
    const outside = harness(enabledConfig);
    outside.emit("session_start", { reason: "new" });
    await outside.command.handler("on", outside.ctx);
    assert.deepEqual(outside.notifications.at(-1), {
      level: "warning",
      message:
        "△ Orchestrator unavailable\n  Requires a Herdr Parent with spawn_pi active.",
    });

    const invalid = harness({
      error: "orchestrator.enabled must be a boolean",
      ok: false,
      path: "/bad.json",
    });
    invalid.emit("session_start", { reason: "new" });
    assert.deepEqual(invalid.notifications.at(-1), {
      level: "warning",
      message:
        "! Orchestrator disabled — invalid config\n  /bad.json\n  orchestrator.enabled must be a boolean\n  spawn_pi blocked",
    });
    assert.equal(
