import { defineConfig } from "oxlint";
import antiSlop from "ultracite/oxlint/anti-slop";
import core from "ultracite/oxlint/core";

export default defineConfig({
  extends: [core, antiSlop],
  ignorePatterns: core.ignorePatterns,
});

import { readFileSync } from "node:fs";

import type {
  ExtensionAPI,
  ExtensionContext,
} from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import type { Static } from "typebox";
import { Check } from "typebox/value";

import type { ChildRolesConfigLoadResult } from "./model-routing.js";

export const ORCHESTRATOR_STATE_ENTRY = "pi-herdr-orchestrator-state";
export const ORCHESTRATOR_INSTRUCTIONS = `Orchestrator mode is enabled. You are the Parent Pi. You own task decomposition, delegation, coordination, synthesis, and final verification.

Proactively delegate useful bounded work with spawn_pi. Use Child Pis for repository exploration, independent implementation with non-overlapping ownership, and review. Batch independent tasks concurrently. Handle trivial work and tightly coupled sequential edits directly.

Children share the current checkout. Avoid overlapping writes, inspect the resulting checkout yourself, treat child reports as inputs rather than proof, and run final verification before responding.`;

const OrchestratorStateSchema = Type.Object({ enabled: Type.Boolean() });
const SessionEntrySchema = Type.Object({
  customType: Type.Optional(Type.String()),
  data: Type.Optional(Type.Unknown()),
  type: Type.String(),
});
type SessionEntry = Static<typeof SessionEntrySchema>;
type OrchestratorGlobal = typeof globalThis & {
  __piHerdrOrchestratorForkState?: boolean;
};

export const findOrchestratorState = (
  entries: readonly SessionEntry[]
): boolean | undefined => {
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = entries[index];
    if (
      entry.type !== "custom" ||
      entry.customType !== ORCHESTRATOR_STATE_ENTRY ||
      !Check(OrchestratorStateSchema, entry.data)
    ) {
      continue;
    }
    return entry.data.enabled;
  }
};

export const readOrchestratorState = (path: string): boolean | undefined => {
  try {
    const entries = readFileSync(path, "utf-8")
      .split("\n")
      .flatMap((line): SessionEntry[] => {
        if (!line.trim()) {
          return [];
        }
        try {
          const entry = JSON.parse(line);
          return Check(SessionEntrySchema, entry) ? [entry] : [];
        } catch {
          return [];
        }
      });
    return findOrchestratorState(entries);
  } catch {
    return undefined;
  }
};

const hasHerdrParentEnvironment = (): boolean =>
  process.env.HERDR_ENV === "1" &&
  Boolean(process.env.HERDR_WORKSPACE_ID) &&
  Boolean(process.env.HERDR_TAB_ID) &&
  Boolean(process.env.HERDR_PANE_ID) &&
  Boolean(process.env.HERDR_SOCKET_PATH);

const unavailableMessage = (
  configResult: ChildRolesConfigLoadResult
): string =>
  configResult.ok
    ? "△ Orchestrator unavailable\n  Requires a Herdr Parent with spawn_pi active."
    : `! Orchestrator disabled — invalid config\n  ${configResult.path}\n  ${configResult.error}\n  spawn_pi blocked`;

export const registerOrchestrator = (
  pi: ExtensionAPI,
  configResult: ChildRolesConfigLoadResult
): void => {
  let enabled = false;

  const available = () =>
    configResult.ok &&
    hasHerdrParentEnvironment() &&
    pi.getActiveTools().includes("spawn_pi");

  const updateStatus = (ctx: ExtensionContext): void => {
    ctx.ui.setStatus(
      "orchestrator",
      enabled && available()
        ? ctx.ui.theme.fg("accent", "orchestrator")
        : undefined
    );
  };

  const persist = (): void => {
    pi.appendEntry(ORCHESTRATOR_STATE_ENTRY, { enabled });
  };

  const setEnabled = (next: boolean, ctx: ExtensionContext): void => {
    if (next && !available()) {
      enabled = false;
      updateStatus(ctx);
      ctx.ui.notify(unavailableMessage(configResult), "warning");
      return;
    }
    enabled = next;
    persist();
    updateStatus(ctx);
    ctx.ui.notify(
      enabled ? "✓ Orchestrator enabled" : "○ Orchestrator disabled",
      "info"
    );
  };

  pi.registerCommand("orchestrator", {
    description: "Toggle or inspect Parent orchestrator mode",
    getArgumentCompletions: (prefix) => {
      const values = ["on", "off", "status", "toggle"];
      const matches = values
        .filter((value) => value.startsWith(prefix))
        .map((value) => ({ label: value, value }));
      return matches.length ? matches : null;
    },
    handler:  async (args, ctx) => {
      const action = args.trim().toLowerCase() || "toggle";
      if (action === "status") {
        const isAvailable = available();
        const message = isAvailable
          ? `${enabled ? "●" : "○"} Orchestrator ${enabled ? "enabled" : "disabled"}`
          : unavailableMessage(configResult);
        const roles =
          isAvailable && configResult.ok
            ? Object.entries(configResult.config.roles)
                .map(([name, role]) =>
                  role.description ? `${name} (${role.description})` : name
                )
                .join(" · ") || "none"
            : undefined;
        ctx.ui.notify(
          roles ? `${message}\n  Roles  ${roles}` : message,
          isAvailable ? "info" : "warning"
        );
        return Promise.resolve();
      }
      if (action === "off") {
        setEnabled(false, ctx);
        return Promise.resolve();
      }
      if (!available()) {
        ctx.ui.notify(unavailableMessage(configResult), "warning");
        return Promise.resolve();
      }
      if (action === "on") {
        setEnabled(true, ctx);
        return Promise.resolve();
      }
      if (action === "toggle") {
        setEnabled(!enabled, ctx);
        return Promise.resolve();
      }
      ctx.ui.notify("! Usage: /orchestrator [on|off|status|toggle]", "error");
      return Promise.resolve();
    },
  });

  pi.on("session_before_fork", () => {
    // SAFETY: This extension owns __piHerdrOrchestratorForkState on globalThis and stores only the local boolean state.
    (globalThis as OrchestratorGlobal).__piHerdrOrchestratorForkState = enabled;
  });

  pi.on("session_start", (event, ctx) => {
    // SAFETY: This extension owns __piHerdrOrchestratorForkState on globalThis and reads it only as an optional boolean.
    const shared = globalThis as OrchestratorGlobal;
    const memoryHandoff =
      event.reason === "fork"
        ? shared.__piHerdrOrchestratorForkState
        : undefined;
    delete shared.__piHerdrOrchestratorForkState;
    const entries = ctx.sessionManager.getEntries();
    const stored = findOrchestratorState(entries);
    const fileHandoff =
      event.reason === "fork" && event.previousSessionFile
        ? readOrchestratorState(event.previousSessionFile)
        : undefined;
    const inherited = memoryHandoff ?? fileHandoff;
    enabled =
      inherited ??
      stored ??
      (configResult.ok ? configResult.config.orchestrator.enabled : false);

    if (!configResult.ok) {
      enabled = false;
      if (ctx.hasUI) {
        ctx.ui.notify(unavailableMessage(configResult), "warning");
      }
    } else if (
      available() &&
      (inherited !== undefined || stored === undefined)
    ) {
      persist();
    }
    updateStatus(ctx);
  });

  pi.on("before_agent_start", (event, ctx) => {
    updateStatus(ctx);
    if (!enabled || !available()) {
      return;
    }
    return {
      systemPrompt: `${event.systemPrompt}\n\n${ORCHESTRATOR_INSTRUCTIONS}`,
    };
  });
};

import { StringEnum } from "@earendil-works/pi-ai";
import type {
  ExtensionAPI,
  Theme,
  ThemeColor,
} from "@earendil-works/pi-coding-agent";
import { Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import type { Static } from "typebox";

import type { BatchRunner } from "./batch.js";
import type {
  BatchProgress,
  ChildResult,
  SpawnBatchResult,
  SpawnTask,
} from "./domain.js";
import { taskIdFor } from "./domain.js";
import { roleGuidance } from "./model-routing.js";
import type { ChildRolesConfigLoadResult } from "./model-routing.js";

const SpawnTaskSchema = Type.Object({
  model: Type.Optional(
    Type.String({ description: "Exact provider/model override", minLength: 1 })
  ),
  prompt: Type.String({
    description: "One independent, bounded task for a fresh Pi",
    minLength: 1,
  }),
  role: Type.Optional(
    Type.String({
      description:
        "Exact configured Child Role name; omit when no matching role is listed",
      minLength: 1,
    })
  ),
  thinking: Type.Optional(
    StringEnum([
      "off",
      "minimal",
      "low",
      "medium",
      "high",
      "xhigh",
      "max",
    ] as const)
  ),
});

export const SpawnPiSchema = Type.Object({
  tasks: Type.Array(SpawnTaskSchema, {
    description: "One to eight independent tasks",
    maxItems: 8,
    minItems: 1,
  }),
});

export type SpawnPiToolInput = Static<typeof SpawnPiSchema>;

type SpawnPiDisplayDetails =
  | { phase: "working"; progress: BatchProgress }
  | { phase: "finished"; result: SpawnBatchResult };

type ChildDisplayState = "working" | "complete" | "needs_input" | "incomplete";
type BatchDisplayState = "working" | "complete" | "needs_input" | "incomplete";

const isControlCharacter = (character: string): boolean => {
  const code = character.codePointAt(0) ?? 0;
  return code <= 0x1f || (code >= 0x7f && code <= 0x9f);
};

const presentationRole = (role: string | undefined): string | undefined => {
  if (role === undefined) {
    return undefined;
  }
  const value = Array.from(role, (character) =>
    isControlCharacter(character) ? " " : character
  )
    .join("")
    .replaceAll(/\s+/gu, " ")
    .trim();
  return value || undefined;
};

const childDisplayState = (
  result: ChildResult | undefined
): ChildDisplayState => {
  if (!result) {
    return "working";
  }
  if (result.status === "succeeded") {
    return "complete";
  }
  if (result.status === "blocked") {
    return "needs_input";
  }
  return "incomplete";
};

const displayLabel = (state: ChildDisplayState | BatchDisplayState): string => {
  if (state === "needs_input") {
    return "needs input";
  }
  return state;
};

const stateIcon = (state: ChildDisplayState | BatchDisplayState): string => {
  if (state === "working") {
    return "◌";
  }
  if (state === "complete") {
    return "✓";
  }
  if (state === "needs_input") {
    return "!";
  }
  return "×";
};

const stateColor = (
  state: ChildDisplayState | BatchDisplayState
): ThemeColor => {
  if (state === "working") {
    return "accent";
  }
  if (state === "complete") {
    return "success";
  }
  if (state === "needs_input") {
    return "warning";
  }
  return "error";
};

const shortReason = (result: ChildResult): string | undefined => {
  if (result.status === "unattributable") {
    return "result unreadable";
  }
  if (result.status === "parent_aborted") {
    return "parent stopped waiting";
  }
  if (result.status !== "failed") {
    return undefined;
  }
  switch (result.error?.code) {
    case "role_not_found": {
      return "role not found";
    }
    case "model_routing_failed": {
      return "model unavailable";
    }
    case "start_failed": {
      return "could not start";
    }
    case "prompt_failed": {
      return "prompt failed";
    }
    case "result_unreadable": {
      return "result unreadable";
    }
    case "parent_aborted": {
      return "parent stopped waiting";
    }
    default: {
      return "unknown failure";
    }
  }
};

const locationText = (result: ChildResult): string | undefined => {
  if (!result.location) {
    return undefined;
  }
  return `${result.location.tabId}/${result.location.paneId}`;
};

const successfulCount = (result: SpawnBatchResult | undefined): number =>
  result?.results.filter((child) => child.status === "succeeded").length ?? 0;

const orderedResults = (results: ChildResult[]): ChildResult[] => {
  const ordered: ChildResult[] = [];
  for (const result of results) {
    const insertionIndex = ordered.findIndex(
      (orderedResult) => orderedResult.requestIndex > result.requestIndex
    );
    if (insertionIndex === -1) {
      ordered.push(result);
    } else {
      ordered.splice(insertionIndex, 0, result);
    }
  }
  return ordered;
};

const batchDisplayState = (
  details: SpawnPiDisplayDetails
): BatchDisplayState => {
  if (details.phase === "working") {
    return "working";
  }
  const { requested, results } = details.result;
  if (results.length !== requested) {
    return "incomplete";
  }
  const states = results.map(childDisplayState);
  if (states.every((state) => state === "complete")) {
    return "complete";
  }
  if (
    states.every((state) => state === "complete" || state === "needs_input")
  ) {
    return "needs_input";
  }
  return "incomplete";
};

const finalBatchStatus = (
  result: SpawnBatchResult,
  state: BatchDisplayState
): string => {
  const completed = successfulCount(result);
  if (state === "complete") {
    const taskLabel = result.requested === 1 ? "task" : "tasks";
    return `${completed} of ${result.requested} ${taskLabel} complete`;
  }
  return `${displayLabel(state)} · ${completed} of ${result.requested} complete`;
};

const summarizeProgress = (progress: BatchProgress): string =>
  `spawn_pi: working · ${progress.completed} of ${progress.total} settled`;

const summarize = (result: SpawnBatchResult): string => {
  const details: SpawnPiDisplayDetails = { phase: "finished", result };
  const batchState = batchDisplayState(details);
  const lines = [
    `spawn_pi: ${stateIcon(batchState)} ${finalBatchStatus(result, batchState)}`,
  ];
  for (const child of orderedResults(result.results)) {
    const state = childDisplayState(child);
    const role = presentationRole(child.role);
    let line = `${stateIcon(state)} ${child.taskId}${role ? ` [${role}]` : ""}`;
    if (state !== "complete") {
      line += `: ${displayLabel(state)}`;
    }
    const reason = shortReason(child);
    if (reason) {
      line += ` · ${reason}`;
    }
    if (child.sessionId) {
      line += ` · session ${child.sessionId}`;
    }
    if (child.error && state !== "complete") {
      line += ` · ${child.error.message}`;
    }
    lines.push(line);
  }
  return lines.join("\n");
};

const renderChildDetails = (
  state: ChildDisplayState,
  result: ChildResult,
  location: string | undefined,
  theme: Theme
): string[] => {
  const details: string[] = [];
  if (state === "complete" && result.summary) {
    details.push(theme.fg("toolOutput", result.summary));
  }
  if (state === "complete" && result.truncated) {
    details.push(theme.fg("muted", "summary truncated"));
  }
  if (
    (state === "needs_input" || state === "incomplete") &&
    result.error?.message
  ) {
    details.push(theme.fg("error", result.error.message));
  }
  if (location && state !== "needs_input") {
    details.push(theme.fg("muted", `location: ${location}`));
  }
  if (result.selection?.model) {
    details.push(
      theme.fg(
        "muted",
        `model: ${result.selection.model.provider}/${result.selection.model.id}`
      )
    );
  }
  if (result.selection?.thinkingLevel) {
    details.push(
      theme.fg("muted", `thinking: ${result.selection.thinkingLevel}`)
    );
  }
  if (result.selection?.modelSource) {
    details.push(
      theme.fg("muted", `model selection: ${result.selection.modelSource}`)
    );
  }
  if (result.selection?.thinkingSource) {
    details.push(
      theme.fg(
        "muted",
        `thinking selection: ${result.selection.thinkingSource}`
      )
    );
  }
  if (result.sessionId) {
    details.push(theme.fg("muted", `session: ${result.sessionId}`));
  }
  return details;
};

const renderChild = (
  taskId: string,
  requestedRole: string | undefined,
  result: ChildResult | undefined,
  expanded: boolean,
  theme: Theme
): string => {
  const state = childDisplayState(result);
  const role = presentationRole(requestedRole);
  let line = `${theme.fg(stateColor(state), stateIcon(state))} ${theme.fg("toolTitle", taskId)}${role ? theme.fg("muted", ` [${role}]`) : ""}`;
  if (state !== "complete") {
    line += ` ${theme.fg(stateColor(state), displayLabel(state))}`;
  }
  const reason = result && shortReason(result);
  if (state === "incomplete" && reason) {
    line += theme.fg("muted", ` · ${reason}`);
  }
  const location =
    result && !result.paneClosed ? locationText(result) : undefined;
  if (state === "needs_input" && location) {
    line += theme.fg("muted", ` · ${location}`);
  }
  if (!expanded || !result) {
    return line;
  }

  const details = renderChildDetails(state, result, location, theme);
  return details.length ? `${line}\n${details.join("\n")}` : line;
};

const displayDetails = (
  value: SpawnPiDisplayDetails | SpawnBatchResult | undefined,
  isPartial: boolean
): SpawnPiDisplayDetails | undefined => {
  if (value === undefined) {
    return undefined;
  }
  if ("phase" in value) {
    return value;
  }
  return isPartial ? undefined : { phase: "finished", result: value };
};

const requestedTasks = (value: {
  tasks?: SpawnTask[];
}): SpawnTask[] | undefined => value.tasks;

const rawText = (
  content: readonly { type: string; text?: string }[]
): string => {
  const text = content.find((part) => part.type === "text");
  return text?.text ?? "spawn_pi finished";
};

const taskCountLabel = (count: number): string => {
  const task = count === 1 ? "task" : "tasks";
  return ` ${count} ${task}`;
};

export const registerSpawnPiTool = (
  pi: ExtensionAPI,
  runner: BatchRunner,
  getParentLabel: () => string,
  configResult: ChildRolesConfigLoadResult
): void => {
  const guidance = configResult.ok
    ? roleGuidance(configResult.config)
    : undefined;
  pi.registerTool<typeof SpawnPiSchema, SpawnPiDisplayDetails>({
    description:
      "Run 1–8 independent bounded tasks concurrently in fresh visible Pi sessions hosted by Herdr. Children share the current checkout and cannot invoke spawn_pi.",
    async execute(_toolCallId, params, signal, onUpdate, ctx) {
      if (!configResult.ok) {
        throw new Error(
          `Invalid Child Roles config at ${configResult.path}: ${configResult.error}`
        );
      }
      const result = await runner.run(
        { tasks: params.tasks },
        {
          cwd: ctx.cwd,
          model: ctx.model
            ? { id: ctx.model.id, provider: ctx.model.provider }
            : undefined,
          parentLabel: getParentLabel(),
          thinkingLevel: ctx.thinkingLevel,
        },
        {
          availableModels: ctx.modelRegistry
            .getAvailable()
            .map((model) => ({ id: model.id, provider: model.provider })),
          config: configResult.config,
        },
        {
          onProgress(progress) {
            onUpdate?.({
              content: [{ text: summarizeProgress(progress), type: "text" }],
              details: {
                phase: "working",
                progress,
              } satisfies SpawnPiDisplayDetails,
            });
          },
          signal,
        }
      );
      return {
        content: [{ text: summarize(result), type: "text" }],
        details: { phase: "finished", result } satisfies SpawnPiDisplayDetails,
      };
    },
    label: "Spawn Pi",
    name: "spawn_pi",
    parameters: SpawnPiSchema,
    promptGuidelines: [
      "Use spawn_pi only for 1–8 independent tasks; children share the checkout and may interfere with concurrent edits.",
      "Set task.role only to an exact name listed under Configured Child Roles; otherwise omit role.",
      ...(guidance ? [guidance] : []),
    ],
    promptSnippet:
      "Offload independent repository exploration or bounded work to fresh visible Pi sessions",
    renderCall(args, theme) {
      const tasks = requestedTasks(args);
      const count = tasks?.length;
      return new Text(
        theme.fg("toolTitle", theme.bold("spawn_pi")) +
          (count === undefined
            ? ""
            : theme.fg("accent", taskCountLabel(count))),
        0,
        0
      );
    },
    renderResult(result, { expanded, isPartial }, theme, context) {
      const details = displayDetails(result.details, isPartial);
      if (!details) {
        return new Text(rawText(result.content), 0, 0);
      }

      const tasks = requestedTasks(context.args);
      const progress =
        details.phase === "working" ? details.progress : undefined;
      const batch = details.phase === "finished" ? details.result : undefined;
      const total = progress?.total ?? batch?.requested ?? tasks?.length ?? 0;
      const settled = new Map<number, ChildResult>();
      for (const childResult of progress?.results ?? batch?.results ?? []) {
        settled.set(childResult.requestIndex, childResult);
      }
      const state = batchDisplayState(details);
      const header =
        details.phase === "working"
          ? `working · ${details.progress.completed} of ${details.progress.total} settled`
          : `${stateIcon(state)} ${finalBatchStatus(details.result, state)}`;
      const lines = [theme.fg(stateColor(state), header)];
      for (let requestIndex = 0; requestIndex < total; requestIndex += 1) {
        const task = tasks?.[requestIndex];
        lines.push(
          renderChild(
            taskIdFor(requestIndex),
            task?.role,
            settled.get(requestIndex),
            expanded,
            theme
          )
        );
      }
      return new Text(lines.join("\n"), 0, 0);
    },
  });
};

